import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`event-production-quote`,heroTitle:`Build event production quotes in minutes`,heroSubtitle:`Perplexity Computer analyzes your uploaded event scope, plans the production needs, and drafts a detailed event quote automatically.`,hasInputUrl:!1,hasInputFile:!0,inputFileCta:`Upload your event scope`,inputFileAccept:`.pdf,.doc,.docx,.csv,.xlsx,.xls,.png,.jpg,.jpeg`,inputFilePrefill:`I've uploaded an event brief, production scope, or RFP. Build a complete event production quote. (1) Extract the event dates, venue details, rooms, show flow, technical requirements, deliverables, and staffing needs from the uploaded materials. (2) Organize the work by production area, including AV, staging, lighting, labor, rehearsal, logistics, and onsite support. (3) Build pricing with line items, assumptions, optional upgrades, and change-order watchouts. (4) Highlight any gaps or dependencies that should be confirmed before sending the quote. (5) Deliver a client-ready production quote with scope summary, budget breakdown, and next steps.`,heroOverlaySteps:[`Extracting the schedule, venue setup, and technical requirements from your files`,`Planning AV, staging, labor, logistics, and onsite support needs`,`Building the quote by production area with assumptions and upgrade options`,`Client-ready production quote with scope summary, ready to send`],generatingSteps:[`Reading the uploaded event brief, RFP, and production requirements`,`Designing an agent to organize the work into production workstreams and staffing needs`,`Configuring quote logic for line items, options, assumptions, and dependencies`,`Preparing a detailed event production quote with budget breakdown and next steps`],featureSectionTitle:`From event scope to production-ready quote`,featureCardTitles:[`Connects to your production workflow`,`Quotes built for complexity and change`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Docs, sheets, run-of-show planning, and internal review workflows stay connected so quoting and handoff are easier for your team.`,`Budget by workstream. Staffing assumptions. Optional upgrades. Change-order watchouts. Computer gives your team a quote draft that is ready for the client.`],capabilitySectionTitle:`Your production desk, on autopilot`,capabilitySectionSubtitle:`Upload the scope, get back a quote built around the real event requirements.`,capabilityCards:[{title:`Scope Analysis`,description:`Computer can extract rooms, schedules, technical requirements, and event flow from RFPs and production briefs so nothing important gets missed.`},{title:`Run of Show Builder`,description:`Computer can organize the project into production workstreams, staffing needs, rehearsals, and onsite support requirements.`},{title:`Budget Breakdown`,description:`Computer can build a line-item budget across AV, staging, labor, logistics, and optional upgrades while keeping assumptions visible.`},{title:`Connect Your Tools`,description:`Computer can keep quote drafts organized across docs, sheets, and production planning workflows so review and handoff stay smooth.`},{title:`Knows Your Vendors`,description:`Computer can remember your preferred vendors, standard inclusions, and pricing guardrails across sessions so quotes stay consistent.`},{title:`Change-Order Tracking`,description:`Computer can flag revision risk and likely change-order points so you can protect margin before the client signs off.`}]});export{t as default};
